function downloadData(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function leaveMode(){pauseMatch();if(mode==='career')career=s;}
function goHome(){leaveMode();mode='home';message('');render();}
function enterDatabase(){leaveMode();mode='database';s=World.context(master);editorClub=s.clubs.some(c=>c.id===editorClub)?editorClub:(s.clubs[0]?.id??'free');view='Base de Dados';message('');render();}
function careerLobby(){leaveMode();mode='lobby';message('');render();}
function continueCareer(){if(!career)return;leaveMode();mode='career';s=career;view='Centro de comando';editorClub=s.managed;division=club(s.managed).div;message('');render();}
function editorSaveMessage(){return mode==='database'?'Alterações aplicadas à Base de Dados Mestre. A gravação automática guarda os dados aplicados neste navegador.':'Alterações aplicadas apenas a esta carreira. A gravação automática guarda os dados aplicados neste navegador.';}
function bindModeNav(){document.querySelectorAll('[data-mode-home]').forEach(b=>b.onclick=goHome);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});}
function renderModeScreen(){
 document.body.dataset.mode=mode;$('advance').hidden=mode!=='career';$('modeHome').onclick=goHome;$('modeHome').hidden=mode==='home';$('modeSave').hidden=!['database','career'].includes(mode);$('modeSave').textContent=mode==='database'?'Exportar base de dados':'Exportar carreira';$('modeSave').onclick=()=>{if(mode==='database'){World.validate(master);downloadData(master,'helvetia-base-mestre.json');}else downloadData(s,`helvetia-${s.year}-j${s.round}.json`);message('Ficheiro exportado. Conserva-o para a próxima sessão.');};
 $('modeLabel').textContent=mode==='database'?'BASE DE DADOS MESTRE · EDIÇÃO':mode==='career'?`CARREIRA · ${s.name||club(s.managed).name} · CÓPIA PRÓPRIA`:'';
 $('footerText').textContent=mode==='career'?'A carreira é guardada neste navegador e não modifica a Base de Dados Mestre. Exporta uma cópia para a conservar fora do navegador.':'Os dados aplicados são guardados neste navegador. As fichas por gravar não são incluídas. Exporta cópias para as conservar noutro local.';
 if(AutoSave.recoveryGate())return true;
 if(mode==='home'){
  $('title').textContent='Helvetia Manager';$('season').textContent='EDIÇÃO SUÍÇA';$('nav').innerHTML='';
  $('app').innerHTML=`<section class="start-heading"><span class="tag">O TEU BANCO. A TUA HISTÓRIA.</span><h2>Por onde queres começar?</h2></section><div class="mode-cards"><section class="panel mode-card"><span class="mode-symbol" aria-hidden="true">▤</span><h2>BASE DE DADOS</h2><p>Explorar e editar o mundo do futebol.</p><p class="muted">${master.players.length} jogadores · ${master.clubs.length} clubes · ${master.staff.length} membros do staff</p><button id="openDatabase" class="primary">Abrir Base de Dados</button></section><section class="panel mode-card"><span class="mode-symbol" aria-hidden="true">◫</span><h2>CARREIRA</h2><p>Transformar os dados numa história.</p><p class="muted">${career?`${esc(career.name||'Carreira em sessão')} · ${career.year}/${String(career.year+1).slice(-2)} · Jornada ${career.round}`:'Podes carregar as tuas carreiras já guardadas.'}</p><button id="openCareer" class="primary">Entrar na Carreira</button></section></div><p class="muted start-note">A Base de Dados funciona por si só. Quando quiseres jogar, cada carreira parte de uma cópia independente.</p><small class="app-version-mobile">Helvetia Manager · v12.28 beta</small>`;
  $('openDatabase').onclick=enterDatabase;$('openCareer').onclick=careerLobby;return true;
 }
 if(mode==='lobby'){
  $('title').textContent='Carreira';$('season').textContent='CONTINUAR OU COMEÇAR';
  $('app').innerHTML=`<div class="mode-cards"><section class="panel mode-card"><h2>Continuar carreira</h2><p>${career?`${esc(career.name||'Carreira em sessão')} · Época ${career.year} · Jornada ${career.round}${career.liveMatch?' · Jogo em curso':''}`:'Carrega um ficheiro de carreira para retomar o teu progresso.'}</p><button id="continueCareer" class="primary" ${career?'':'disabled'}>Continuar a carreira em sessão</button><button id="loadCareer">Carregar carreira de ficheiro</button><p class="muted">Carregar uma carreira não altera a Base de Dados Mestre.</p></section><section class="panel mode-card"><h2>Nova carreira</h2><form id="newCareerForm"><label>Nome da carreira<input id="careerName" maxlength="100" required value="Nova carreira"></label><label>Clube a gerir<select id="newCareerClub">${master.clubs.filter(c=>[0,1].includes(c.div)).map(c=>`<option value="${c.id}" ${c.id===12?'selected':''}>${esc(c.name)} · ${esc(league(c.div))}</option>`).join('')}</select></label><p class="muted">Base: ${esc(master.name)} · Época ${master.year}/${String(master.year+1).slice(-2)}. As futuras edições da Mestre não alteram esta carreira.</p><button class="primary" type="submit">Criar carreira a partir da Mestre</button><p id="newCareerError" role="alert"></p></form></section></div>`;
  $('continueCareer').onclick=continueCareer;$('loadCareer').onclick=()=>$('importFile').click();$('newCareerForm').onsubmit=async e=>{e.preventDefault();try{const next=World.createCareer(master,+$('newCareerClub').value,$('careerName').value);if(career&&!confirm('Substituir a carreira em sessão? Guarda-a antes se quiseres continuar mais tarde.'))return;await AutoSave.settle();AutoSave.forceNext('career');career=next;continueCareer();}catch(err){$('newCareerError').textContent=err.message;}};return true;
 }
 if(mode!=='database')return false;
 $('nav').innerHTML=['Base de Dados','Pesquisa global','Todos os jogadores','Plantel e staff','Editor de clubes','Editor de competições'].map(v=>`<button data-view="${v}" class="${view===v?'active':''}">${v}</button>`).join('');$('title').textContent=view;$('season').textContent=`${master.name} · REFERÊNCIA ${master.year}`;bindModeNav();
 if(view==='Base de Dados'){
  $('app').innerHTML=`<div class="database-banner">Estás a editar a Mestre. Nenhuma carreira em curso será modificada.</div><div class="toolbar"><button id="loadMaster">Carregar base de dados</button><button id="seedMasterFromCareer">Importar dados de uma carreira</button><button id="clearMaster" class="danger">Limpar Base Mestre…</button></div><div class="mode-cards"><section class="panel"><h2>Registos</h2><div class="database-links"><button data-view="Todos os jogadores">Pesquisar todos os jogadores · filtros · verificação</button><button data-view="Plantel e staff">${master.players.length} jogadores e ${master.staff.length} membros do staff</button><button data-view="Editor de clubes">${master.clubs.length} clubes · estádios · cidades · logótipos</button><button data-view="Editor de competições">${master.competitions.length} competições · regras · participantes</button></div></section><section class="panel"><h2>Dados gerais</h2><form id="masterSettings"><label>Nome da base<input name="name" maxlength="100" required value="${esc(master.name)}"></label><label>Ano inicial das novas carreiras<input name="year" type="number" min="2026" max="2100" required value="${master.year}"></label><label>Notas<textarea name="notes" maxlength="5000">${esc(master.notes)}</textarea></label><button type="submit">Aplicar dados gerais</button><p id="masterError" role="alert"></p></form></section></div><p class="muted">A Mestre não contém jogos em curso nem resultados de simulação. A gravação automática funciona sem criar uma carreira. Usa Recuperação para consultar cópias anteriores e exporta também os dados para ficheiro.</p>`;
  $('clearMaster').onclick=()=>AutoSave.showReset();$('loadMaster').onclick=()=>{masterImportKind='database';$('masterFile').click();};$('seedMasterFromCareer').onclick=()=>{masterImportKind='career';$('masterFile').click();};$('masterSettings').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),candidate={...master,name:f.get('name').trim(),year:+f.get('year'),notes:f.get('notes').trim()};try{World.validate(candidate);master=candidate;s=World.context(master);render();message(editorSaveMessage());}catch(err){$('masterError').textContent=err.message;}};mountDatabaseHealth();mountCsvExport();bindModeNav();return true;
 }
 if(view==='Pesquisa global'){renderDatabaseSearch();return true;}
 if(view==='Todos os jogadores'){renderPlayerBrowser();return true;}
 if(view==='Editor de competições'){renderCompetitionsEditor();return true;}return false;
}
let masterImportKind='database';
async function importMasterFile(e){try{const file=e.target.files[0];if(!file)return;if(file.size>100e6)throw Error('Ficheiro demasiado grande.');const data=JSON.parse(await file.text());const incoming=masterImportKind==='career'?World.fromCareer(data):World.validate(data);if(!confirm('Substituir a Mestre em sessão? As carreiras não serão alteradas. Será criado um backup protegido da Mestre actual em Recuperação antes da substituição.'))return;await AutoSave.replaceMaster(incoming);enterDatabase();message('Base de Dados Mestre carregada. As carreiras existentes mantêm os seus dados.');}catch(err){message('Não foi possível carregar a base: '+err.message);}finally{e.target.value='';}}
